"""Service catalog (generated by scripts/build_service_catalog.py) and botocore model introspection."""

from __future__ import annotations

import functools
import json
import re
from pathlib import Path
from typing import Any

import botocore.session
from botocore.model import OperationModel, Shape

CATALOG_PATH = Path(__file__).with_name("catalog.json")

# Verb prefixes -> operation group. Order matters: first match wins.
_GROUPS: list[tuple[str, tuple[str, ...]]] = [
    (
        "delete",
        tuple(
            """Delete Remove Terminate Purge Deregister Unregister Disassociate Detach Untag Revoke Disable
            Cancel Stop Reject Release Abort Destroy Unsubscribe Unlink Unassign Unshare Unpublish Withdraw
            Decline Close""".split()
        ),
    ),
    (
        "read",
        tuple(
            """List Describe Get Search Query Scan Lookup BatchGet Check Validate Test Preview Estimate Head
            Select Download Simulate Evaluate Detect Discover Verify Explain Count View Retrieve Fetch Poll
            Receive""".split()
        ),
    ),
    (
        "create",
        tuple(
            """Create Put Add Register Import Start Run Upload Publish Send Tag Associate Attach Enable Copy
            Request Allocate Authorize Invoke Subscribe Batch Accept Assign Submit Generate Deploy Provision
            Link Share Clone Execute Activate Apply Grant Encrypt Decrypt Sign Initiate Complete""".split()
        ),
    ),
    (
        "update",
        tuple(
            """Update Modify Set Change Reset Restore Rotate Replace Reboot Resume Pause Edit Move Rename
            Promote Upgrade Increase Decrease Enter Exit""".split()
        ),
    ),
]

DESTRUCTIVE = re.compile(r"^(Delete|Terminate|Remove|Purge|Deregister|Destroy|Unregister)")


@functools.cache
def services() -> dict[str, dict[str, Any]]:
    data = json.loads(CATALOG_PATH.read_text())
    return {entry["id"]: entry for entry in data["services"]}


@functools.cache
def icon_package() -> str:
    return json.loads(CATALOG_PATH.read_text()).get("iconPackage", "")


@functools.cache
def _botocore():
    return botocore.session.get_session()


def model(service: str):
    if service not in services():
        raise KeyError(service)
    return _botocore().get_service_model(service)


def operation(service: str, name: str) -> OperationModel:
    m = model(service)
    if name not in m.operation_names:
        raise KeyError(f"{service}.{name}")
    return m.operation_model(name)


def group_of(op_name: str) -> str:
    for group, prefixes in _GROUPS:
        if op_name.startswith(prefixes):
            return group
    return "other"


def is_destructive(op_name: str) -> bool:
    return bool(DESTRUCTIVE.match(op_name))


def plain_docs(html: str | None, limit: int = 1500) -> str:
    text = re.sub(r"<[^>]+>", " ", html or "")
    text = re.sub(r"\s+", " ", text).strip()
    return text if len(text) <= limit else text[: limit - 1] + "…"


def skeleton(
    shape: Shape | None, *, required_only: bool, depth: int = 0, seen: frozenset[str] = frozenset()
) -> Any:
    """An example JSON value for a botocore input shape (what the operation runner pre-fills)."""
    if shape is None:
        return {}
    if shape.name in seen or depth > 5:
        return None  # recursive shape - leave for the user to fill in
    seen = seen | {shape.name}
    kind = shape.type_name
    if kind == "structure":
        names = shape.required_members if required_only else list(shape.members)
        return {
            n: skeleton(shape.members[n], required_only=required_only, depth=depth + 1, seen=seen)
            for n in names
            if n in shape.members
        }
    if kind == "list":
        return [skeleton(shape.member, required_only=required_only, depth=depth + 1, seen=seen)]
    if kind == "map":
        return {"key": skeleton(shape.value, required_only=required_only, depth=depth + 1, seen=seen)}
    if kind == "string":
        enum = shape.enum
        return enum[0] if enum else ""
    if kind in ("integer", "long"):
        return 0
    if kind in ("float", "double"):
        return 0.0
    if kind == "boolean":
        return False
    if kind == "timestamp":
        return "2026-01-01T00:00:00Z"
    if kind == "blob":
        return {"__bytes__": ""}
    return None


def member_docs(shape: Shape | None) -> list[dict[str, Any]]:
    if shape is None:
        return []
    required = set(shape.required_members)
    return [
        {
            "name": name,
            "type": member.type_name,
            "required": name in required,
            "enum": member.enum if member.type_name == "string" else [],
            "doc": plain_docs(member.documentation, 300),
        }
        for name, member in shape.members.items()
    ]


def list_member_count(output: dict[str, Any]) -> int:
    """Number of items in the first top-level list of an operation's response."""
    for key, value in output.items():
        if key != "ResponseMetadata" and isinstance(value, list):
            return len(value)
    return 0
